O.snipeOn,O.snipeUnit=true,Dud[727]
end
if O.pickPortal==Dud[573]then
O.portals,O.pickPortal=false,Dud[572]
end
if O.huntCards==Dud[1656]then
O.huntCards=Dud[1657]
end
