if not O.simpleGui then
O.simpleGui=true
if not O.play then
O.master=false
end
O.play=true
for mc,nc in ipairs({Dud[1658],Dud[1659],Dud[1660],Dud[1661],Dud[1662],Dud[1663],Dud[1664],Dud[1665]})do
O[nc]=true
end
end
end
