table.sort(Fn)
En=Fn[math.floor(#Fn/2)+1]
end
local Gn=type(P.hunt.starfall)==Dud[1645]and P.hunt.starfall or{}
local Hn=(tonumber(Gn.runs)or 0)+1
local In=1/math.min(Hn,5)
P.hunt.starfall={runs=Hn,perWave=Gn.perWave and(Gn.perWave+(Dn-Gn.perWave)*In)or Dn,hpK=En and(Gn.hpK and(Gn.hpK+(En-Gn.hpK)*In)or En)or Gn.hpK,at=os.time()}
local Jn,Kn
