F.saveSoon()
F.log(1,Dud[1904],string.format(Dud[1905],kb.charmWords(_p),tostring(Zp.label),math.floor((tonumber(Zp.p)or 0)*100+0.5),(tonumber(Zp.p)or 0)>=0.92 and Dud[1896]or Dud[1807]))
