function kb.weatherStrength(cq)
local dq=kb.fx(cq)
local eq=dq.dmg/dq.cd/dq.hp/dq.speed*(1+(dq.range-1)/2)
for fq,gq in pairs(dq.kinds)do
eq=eq*(1+bb.rogueShare(fq)*gq)
end
if dq.ice>0 then
local hq=bb.rogueShare(Dud[1779])
eq=eq*(hq+(1-hq)/(1-dq.ice+dq.ice/fb.modFactor(Dud[1907])))
end
if dq.fly>0 then
eq=eq*(1-dq.fly*0.5)
end
if dq.noCC then
eq=eq*0.95
end
if dq.shroud then
eq=eq*0.9
end
if dq.zap then
eq=eq*0.85
end
return eq/kb.weatherK(cq)
end
kb.WEATHER_K_MIN,kb.WEATHER_K_MAX,kb.WEATHER_K_RUNS=0.5,4,10
function kb.weatherK(iq)
local jq=iq and type(P.hunt)==Dud[1645]and type(P.hunt.wk)==Dud[1645]and P.hunt.wk[tostring(iq)]or nil
return type(jq)==Dud[1645]and tonumber(jq.k)or 1
end
function kb.weatherLearn()
if bb.withOthers or#game:GetService(Dud[549]):GetPlayers()>1 then
return
end
local kq=bb.huntWeather or kb.weatherNow()
local lq,mq=bb.pred,bb.calRun
if not kq or type(lq)~=Dud[1645]or type(mq)~=Dud[1645]then
return
end
local function nq(oq,pq)
return type(oq)==Dud[1645]and tonumber(oq[pq]or oq[tostring(pq)])or nil
end
local qq={}
for rq=2,bb.wave()do
local sq,tq=nq(mq.alive,rq),nq(lq.aliveAt,rq)
if sq and tq and sq>0 and tq>0 then
table.insert(qq,sq/tq)
end
end
if#qq<3 then
return
end
table.sort(qq)
local uq=qq[math.ceil(#qq/2)]
P.hunt.wk=type(P.hunt.wk)==Dud[1645]and P.hunt.wk or{}
local vq=P.hunt.wk[tostring(kq)]
local wq=math.min(kb.WEATHER_K_RUNS-1,type(vq)==Dud[1645]and tonumber(vq.n)or 0)
local xq=kb.weatherK(kq)
local yq=math.max(1,wq)
local zq=math.exp((yq*math.log(xq)+math.log(xq*uq))/(yq+1))
zq=U.clamp(zq,kb.WEATHER_K_MIN,kb.WEATHER_K_MAX)
bb.wkWas={w=tostring(kq),old=vq}
P.hunt.wk[tostring(kq)]={k=zq,n=(type(vq)==Dud[1645]and tonumber(vq.n)or 0)+1,at=os.time()}
F.log(1,Dud[1908],string.format(Dud[1909],tostring(kq),uq,tostring(kq),zq,xq,P.hunt.wk[tostring(kq)].n))
end
