W.MATCHED_DAILY_P=0.7
function W.winP(az)
if az.kind==Dud[1824]and O.dailyMatch and not O.dailyLoop then
local bz,cz=pcall(W.needsHelp,az)
if bz and cz then
return W.MATCHED_DAILY_P
end
end
local dz=az.rec
local ez=az.p0 or W.PRIOR_WIN[az.kind]or 0.7
local fz=W.sim(az)
if fz and not(fz.trust and not fz.trust.ok)then
local gz=fz.calibrated or dz.runs>0
local hz=(fz.trust and fz.trust.ok)and 6 or(gz and 3 or 1.5)
local iz=(gz or fz.hopeless)and 0 or 2
local jz,kz=pcall(fb.styleP,fz)
return(dz.wins+ez*iz+(jz and kz or fz.p)*hz)/(dz.runs+iz+hz)
end
return(dz.wins+ez*2)/(dz.runs+2)
end
function W.minutes(lz)
local mz=lz.rec
local nz=tonumber(mz.timed)or 0
local oz=lz.kind==Dud[1664]and P.simRes[lz.key]
local pz=(nz>0 and mz.sec>0)and(mz.sec/nz/60)or(oz and tonumber(oz.minutes))or W.PRIOR_MIN[lz.kind]or 6
return pz+W.OVERHEAD
end
function W.score(qz)
local rz,sz=((qz.kind==Dud[1662]and qz.rec.runs>0)or qz.kind==Dud[1664]or qz.kind==Dud[1827])and 1 or(qz.kind==Dud[1665]and qz.p0)or W.winP(qz),W.minutes(qz)
local tz,uz,vz=pcall(jb.modeBonus,qz)
if tz and(uz or 0)>0 then
qz.teamBonus=uz
if not tostring(qz.why):find(Dud[2090],1,true)then
qz.why=(qz.why or Dud[570])..Dud[1874]..vz
end
end
local wz=rz*(qz.value+(qz.teamBonus or 0))/sz
qz.baseScore=wz
local xz,yz,zz=pcall(hb.valueFor,qz)
if xz and yz>0 then
local Az=rz*(qz.value+yz)/(sz*zz)
if Az>wz then
wz,qz.train=Az,yz
end
end
if qz.rec.runs<2 then
wz=wz*(1+O.exploreBonus)
