local MH={}
for NH,OH in pairs(LH and LH.rateup_units or{})do
if type(OH)==Dud[1645]and type(OH.possible_units_set)==Dud[1645]then
for PH in pairs(OH.possible_units_set)do
table.insert(MH,PH)
end
end
end
local QH={}
for RH,SH in ipairs(MH)do
local TH,UH=gb.tierBest(SH)
table.insert(QH,{r=UH,text=string.format(Dud[2248],V.name(TH),(gb.tier(TH))or Dud[2249],V.owns(SH)and Dud[2250]or Dud[570])})
end
table.sort(QH,function(VH,WH)
return VH.r>WH.r
end)
local XH={}
for YH,ZH in ipairs(QH)do
table.insert(XH,ZH.text)
end
if#XH>0 then
table.insert(GH,string.format(Dud[2251],IH,KH,table.concat(XH,Dud[1874])))
end
end
HH(Dud[2252],Dud[2253],Dud[2254])
HH(Dud[2255],Dud[2256],Dud[2257])
HH(Dud[2258],Dud[2259],Dud[2260])
local _H={}
for aI,bI in ipairs(V.equipped())do
if not V.isFarm(bI.id)and not V.allyBuff(bI.id)then
local cI,dI=V.types(bI.id)
if dI then
_H[dI]=true
end
end
end
local eI,fI={},{}
for gI,hI in pairs(FH.collection.owned_units)do
local iI,jI=gb.tierBest(hI.unit_id)
if jI>=4 and not fI[iI]then
fI[iI]=true
local kI=Dud[570]
local lI=V.allyBuff(iI)
if lI then
local mI=false
for nI in pairs(lI.types or{})do
if _H[nI]then
mI=true
end
end
if not mI then
for oI in pairs(lI.types or{})do
kI=string.format(Dud[2261],oI)
end
end
end
if iI~=hI.unit_id then
kI=kI..Dud[2262]..V.name(hI.unit_id)..Dud[2029]
end
table.insert(eI,{r=jI,text=V.name(iI)..Dud[1816]..((gb.tier(iI))or Dud[570])..kI})
end
end
table.sort(eI,function(pI,qI)
return pI.r>qI.r
end)
local rI={}
for sI,tI in ipairs(eI)do
if sI<=8 then
table.insert(rI,tI.text)
end
end
if#rI>0 then
table.insert(GH,Dud[2263]..table.concat(rI,Dud[1874]))
end
table.insert(GH,Dud[2264]..Dud[2265])
return table.concat(GH,Dud[1655])
end
function gb.pullGoal()
local uI=O.pullGoal
if type(uI)~=Dud[556]or uI==Dud[570]or type(N.Units[uI])~=Dud[1645]then
return nil
end
local vI=N.prof()
if not vI then
return nil
end
local wI=N.Units[uI]
local xI=wI.evolve and wI.evolve.evolve_unit or uI
local yI={id=uI,to=xI,coins=N.cur(Dud[2266]),itemCost=0,needCoins=0}
for zI,AI in pairs(wI.evolve and wI.evolve.normal and wI.evolve.normal.item_requirement or{})do
local BI=N.SaleEvent[AI.item_id]
if BI and type(BI.resource_cost)==Dud[1645]and BI.resource_cost.id==Dud[2266]then
yI.item,yI.itemCost=AI.item_id,tonumber(BI.resource_cost.amount)or 0
end
end
yI.haveItem=yI.item~=nil and gb.have(yI.item)>0
local CI,DI=ab.hatched[uI]or false,false
for EI,FI in pairs(vI.collection.owned_units)do
if FI.unit_id==uI then
CI=true
end
if FI.unit_id==xI then
DI=true
end
end
if DI then
yI.step=Dud[2267]
elseif not CI then
yI.step,yI.needCoins=Dud[2268],1
elseif yI.item and not yI.haveItem then
yI.step,yI.needCoins=Dud[2237],math.max(0,yI.itemCost-yI.coins)
else
yI.step=Dud[1739]
end
return yI
end
function gb.goalText()
local GI=gb.pullGoal()
if not GI then
return Dud[2269]
end
local HI=N.prof()
local II=string.format(Dud[2270],V.name(GI.to),(gb.tier(GI.to))and(Dud[2271]..gb.tier(GI.to)..Dud[2029])or Dud[570])
if GI.step==Dud[2268]then
if not N.Banners.April2025 then
return II..string.format(Dud[2272],V.name(GI.id))
end
local JI=math.max(O.aprilFloor,GI.haveItem and 0 or GI.itemCost)
local KI=HI and HI.pity_data and HI.pity_data.April2025
local LI=KI and tonumber(KI.opens_since_mythic)
return II..string.format(Dud[2273]..Dud[2274]..Dud[2275],V.name(GI.id),U.fmt(GI.coins),math.max(0,math.floor((GI.coins-JI)/1500)),U.fmt(JI),V.name(GI.id),LI and string.format(Dud[2276],LI)or Dud[570],math.max(O.aprilValue,O.goalCoinValue),O.summonApril and Dud[2277]or Dud[2278])
elseif GI.step==Dud[2237]then
return II..string.format(Dud[2279],V.name(GI.id),U.fmt(GI.itemCost),U.fmt(GI.coins))
elseif GI.step==Dud[1739]then
return II..Dud[2280]
end
return II..Dud[2281]
end
function ab.eventShop()
local MI=gb.pullGoal()
if not(O.summonApril and MI and MI.step==Dud[2237]and MI.coins>=MI.itemCost and MI.itemCost>0)then
return
end
if F.req.back.eshop and U.now()<F.req.back.eshop then
return
end
local NI,OI=F.request(Dud[2282],Dud[1978],MI.item,Dud[1662],Dud[1979],Dud[1811])
local PI=U.now()
while U.now()-PI<4 and gb.have(MI.item)<1 do
task.wait(0.25)
end
local QI=(N.Items[MI.item]or{}).name or MI.item
if gb.have(MI.item)>0 then
cb.add(QI,MI.itemCost,Dud[2266],Dud[2283]..V.name(MI.to))
if F.notify then
F.notify(Dud[71],Dud[2284]..QI..Dud[2285]..V.name(MI.id),Dud[2286])
end
pcall(gb.refresh)
else
F.log(1,Dud[2287],Dud[2288]..tostring(MI.item)..Dud[2055]..tostring(NI and OI or Dud[1961])..Dud[2029])
F.backoff(Dud[2282],900)
end
end
function ab.codes()
if not O.codes then
return F.status(Dud[99],Dud[2289])
end
local RI=N.prof()
if not RI then
return
end
local SI=RI.redeemed_codes or{}
local TI,VI={},{}
for WI,XI in ipairs(N.CODES)do
local YI=tonumber(P.codes[XI])
if SI[XI]then
if YI and YI>0 then
table.insert(VI,XI)
P.codes[XI]= -1
end
elseif os.time()-(YI or 0)>86400 and(YI or 0)>=0 then
P.codes[XI]=os.time()
local ZI=F.request(Dud[2290],Dud[2291],XI)
if ZI then
table.insert(TI,XI)
end
task.wait(1)
end
end
if#VI>0 then
F.log(1,Dud[2292],Dud[2293]..table.concat(VI,Dud[1755]))
pcall(F.feed,Dud[2017],Dud[2294],table.concat(VI,Dud[1755]))
end
if#TI>0 then
F.log(1,Dud[2292],Dud[2295]..table.concat(TI,Dud[1755])..Dud[2296])
end
F.saveSoon()
local _I=0
for aJ,bJ in ipairs(N.CODES)do
if not SI[bJ]then
_I=_I+1
end
end
F.status(Dud[99],#TI>0 and(Dud[2295]..table.concat(TI,Dud[1755]))or(_I==0 and Dud[2297]or(_I..Dud[2298])))
end
