function gb.planItem(vJ,wJ)
local xJ=gb.have(vJ)
if xJ>=wJ then
return{item=vJ,done=true}
end
local yJ=gb.sources()[vJ]
if yJ and yJ[1]then
return{item=vJ,need=wJ,have=xJ,farm=vJ,farmNeed=wJ-xJ,levels=yJ}
end
local zJ=N.SaleEvent[vJ]
if zJ and type(zJ.resource_cost)==Dud[1645]then
return{item=vJ,need=wJ,have=xJ,eventShop=true,cost=tonumber(zJ.resource_cost.amount)or 0,currency=zJ.resource_cost.id,farmNeed=0}
end
for AJ,BJ in pairs(P.raidShop)do
if BJ.id==vJ and BJ.costItem and(BJ.stock==Dud[2299]or(tonumber(BJ.stock)or 0)>0)then
local CJ=gb.sources()[BJ.costItem]
local DJ=BJ.cost*(wJ-xJ)
local EJ=gb.have(BJ.costItem)
return{item=vJ,need=wJ,have=xJ,shopKey=AJ,costItem=BJ.costItem,cost=BJ.cost,farm=BJ.costItem,farmNeed=math.max(0,DJ-EJ),levels=CJ or{}}
end
end
for FJ,GJ in pairs(W.PORTALS)do
if GJ.item==vJ then
return{item=vJ,need=wJ,have=xJ,farm=vJ,farmNeed=wJ-xJ,portal=FJ,levels={{level=GJ.level,per=W.portalPer(FJ)}}}
end
