W._spawns={}
function W.levelSpawns(XJ,YJ)
local ZJ=tostring(XJ)
local _J=W._spawns[ZJ]
if _J and os.time()-_J.at<3600 then
return _J.n
end
local aK=0
pcall(function()
local bK=N.Levels[XJ]
local cK=fb.info(fb.slim and fb.slim(bK)or bK,Dud[2304]..ZJ)
local dK=false
for eK,fK in pairs(cK.configs or{})do
if YJ[eK]or(type(fK)==Dud[1645]and YJ[fK.unit_id or Dud[570]])then
dK=true
break
end
end
if not dK then
return
end
local gK=cK.infinite and math.floor(W.infReach(Dud[1817]..ZJ)+0.5)or cK.total
local function hK(iK)
local jK=cK.configs[iK]
return YJ[iK]or(type(jK)==Dud[1645]and YJ[jK.unit_id or Dud[570]])
end
for kK=1,math.min(gK or 30,200)do
if cK.infinite then
local lK,mK=pcall(N.LU.Infinite.infinite_amt_scale,kK,cK.ld)
local nK,oK=0,0
for pK,qK in pairs(cK.configs)do
if type(qK)==Dud[1645]and qK.spawn_tier_normal then
local rK,sK=pcall(N.LU.Infinite.infinite_get_normal_unit_chance,qK,kK)
sK=rK and tonumber(sK)or 0
nK=nK+sK
if hK(pK)then
oK=oK+sK
end
end
end
if nK>0 then
aK=aK+(lK and tonumber(mK)or 10)*oK/nK
end
else
local tK=cK.list[kK]
for uK,vK in ipairs(U.list(tK and tK.wave))do
if hK(vK.unit)then
aK=aK+(tonumber(vK.amount)or 1)
end
end
end
end
aK=math.floor(aK+0.5)
end)
W._spawns[ZJ]={n=aK,at=os.time()}
return aK
end
function W.missionValue(wK)
local xK=N.session()
local yK,zK=0,nil
for AK,BK in pairs(xK and xK.quest_handler.quest_profile_data.quests or{})do
local CK=BK.quest_info
local DK=CK and CK.quest_class
if DK and DK.class==Dud[2305]and type(DK.unit_ids)==Dud[1645]then
local EK=tonumber(DK.amount)or 0
local FK=EK-(tonumber(BK.quest_progress and BK.quest_progress.amount)or 0)
if FK>0 then
local GK=W.levelSpawns(wK,DK.unit_ids)
if GK>0 then
local HK=tonumber(CK.quest_reward and CK.quest_reward.gem_reward)or 0
for IK,JK in pairs(CK.quest_reward and CK.quest_reward.item or{})do
if type(JK)==Dud[1645]and JK.item_id then
HK=HK+W.itemValue(JK.item_id,tonumber(JK.max_amount or JK.amount or JK.min_amount)or 1)
end
end
yK=yK+HK*math.min(1,GK/FK)
zK=string.format(Dud[2306],tostring(CK.quest_name),U.fmt(EK-FK),U.fmt(EK),U.fmt(math.min(GK,FK)))
end
end
end
end
return yK,zK
end
function W.portalKinds()
