table.sort(NK)
local PK={}
local function QK(RK,SK)
if type(RK)~=Dud[1645]or SK>4 then
return
end
if type(RK.item_id)==Dud[556]then
PK[RK.item_id]=true
end
for TK,UK in pairs(RK)do
QK(UK,SK+1)
end
end
for VK,WK in ipairs(NK)do
QK((N.Levels[WK]or{}).rewards,0)
end
if W.PORTALS[LK]then
PK[W.PORTALS[LK].item]=true
end
table.insert(KK,{pid=LK,name=MK.name or LK,rarity=MK.rarity,levels=NK,drops=PK})
end
end
table.sort(KK,function(XK,YK)
if XK.name~=YK.name then
return XK.name<YK.name
end
return XK.pid<YK.pid
end)
W._kinds=KK
