function W.portalMod(rL)
local sL,tL={weak={},strong={},res={}},false
for uL,vL in pairs(type(rL.weak)==Dud[1645]and rL.weak or{})do
local wL=type(vL)==Dud[1645]and vL.damage_type or(type(vL)==Dud[556]and vL)or nil
if wL and wL~=Dud[570]then
tL=true
sL.weak[wL]=W.weakAmp(type(vL)==Dud[1645]and vL.amplification)
end
end
for xL,yL in pairs(type(rL.strong)==Dud[1645]and rL.strong or{})do
local zL=type(yL)==Dud[1645]and yL.damage_type or(type(yL)==Dud[556]and yL)or nil
local AL=type(yL)==Dud[1645]and tonumber(yL.amplification)
if zL and zL~=Dud[570]then
tL=true
if AL and AL<1 then
sL.res[zL]=AL
else
sL.strong[zL]=true
end
end
end
return tL and sL or nil
end
function W.weakAmp(BL)
BL=tonumber(BL)
if not BL then
return 1.5
end
return 1+math.max(0,BL)
end
function W.portalFit(CL,DL)
local EL=W.portalMod(CL)
if not EL then
return 1
end
local FL,GL=0,0
for HL,IL in ipairs(DL or{})do
if not V.isFarm(IL.id)and not V.allyBuff(IL.id)then
local JL,KL=pcall(V.score,IL.u)
KL=JL and tonumber(KL)or 0
FL=FL+KL
GL=GL+KL*V.elem(IL.id,EL)
end
end
return FL>0 and GL/FL or 1
end
function W.portalRows()
local LL={}
local ML=O.pickPortal or Dud[572]
if ML==Dud[573]or O.portals==false then
return LL
end
local NL=ab.badPortal or{}
local OL=P.testTeam
local function PL(QL)
for RL,SL in ipairs(W.portalKinds())do
local TL=QL or ML==SL.pid or(OL and(OL.left or 0)>0 and OL.pid==SL.pid)
if TL or ML==Dud[572]then
