local cM=not bM or(NL[aM.uuid]or 0)<(NL[bM.uuid]or 0)or((NL[aM.uuid]or 0)==(NL[bM.uuid]or 0)and aM.fit>bM.fit)
if cM then
YL[aM.tier]=aM
end
