local gM=tonumber(N.Levels[fM]._override_gem_reward)or 0
local hM,iM=gM,{}
local jM=W.PORTALS[SL.pid]
for kM,lM in ipairs(VL)do
local mM,nM=1,true
if jM and jM.item==lM then
mM,nM=W.portalPer(SL.pid)
end
hM=hM+W.itemValue(lM,mM)
table.insert(iM,string.format(Dud[2308],U.fmt(mM),(N.Items[lM]or{}).name or lM,nM and Dud[570]or Dud[2309]))
end
local oM,pM=pcall(db.hiveDrops,fM)
for qM,rM in pairs(oM and type(pM)==Dud[1645]and pM or{})do
if not table.find(VL,qM)then
hM=hM+W.itemValue(qM,tonumber(rM)or 0)
end
