function jb.relicWorth(NQ,OQ)
local PQ=OQ._unique_item_data and OQ._unique_item_data._unique_relic_data
if not PQ then
return 0
end
local QQ=N.Items[OQ.item_id]or{}
local RQ,SQ=V.types(NQ.unit_id)
if QQ.main_damage_type and QQ.main_damage_type~=Dud[2359]and QQ.main_damage_type~=SQ then
return 0
end
local TQ,UQ=0,0
for VQ,WQ in pairs(PQ._core_damage_type_buffs or{})do
if RQ[WQ.damage_type]then
TQ=TQ+(tonumber(WQ.mul)or 0)+(tonumber(WQ.add_upg)or 0)*0.01+(tonumber(WQ.pen)or 0)*0.001
UQ=UQ+(tonumber(WQ.crit)or 0)
end
end
TQ=TQ+UQ*0.5
local XQ=V.rows(NQ.unit_id)
local YQ=XQ and XQ[XQ.max]
local ZQ=(YQ and tonumber(YQ.cd)or 0)*V.mult(NQ,Dud[1808])
for _Q,aR in pairs(PQ._unique_relic_effects or{})do
local bR=type(aR.params)==Dud[1645]and aR.params or{}
if aR.id==Dud[2360]then
local cR=math.min(1,(tonumber(bR.extra_damage)or 0)*ZQ/math.max(1,tonumber(bR.time_interval)or 40))
local dR=V.DRONES and V.DRONES[NQ.unit_id]
if dR and dR.late and ZQ>0 then
local eR=1/ZQ
cR=cR*eR/(eR+(tonumber(dR.max)or 0)*(tonumber(dR.late.dmg)or 0)*(tonumber(dR.hits)or 1)/math.max(0.1,tonumber(dR.late.cd)or 4))
end
TQ=TQ+cR
elseif aR.id==Dud[2361]then
TQ=TQ+(tonumber(bR.dmg_buff)or 0)*0.25
elseif aR.id==Dud[2362]then
TQ=TQ+(tonumber(bR.dmg_buff)or 0)*UQ
elseif aR.id==Dud[2363]then
if RQ.magic then
TQ=0
else
TQ=TQ+(tonumber(bR.dmg_buff)or 0)*0.3
end
elseif aR.id==Dud[2364]then
if RQ.water_damage then
TQ=TQ+0.05
end
end
end
return TQ
end
function jb.relicPlan()
local fR=N.session()
if not fR then
return nil
end
local gR=fR.inventory and fR.inventory.inventory_profile_data or{}
local hR={}
for iR,jR in ipairs(gR.unique_items or{})do
if type(jR)==Dud[1645]and jR.uuid and(N.Items[jR.item_id]or{}).item_group==Dud[2365]then
table.insert(hR,jR)
end
end
local kR={}
for lR,mR in ipairs(V.equipped())do
local nR=mR.data and mR.data.rarity
if not V.isFarm(mR.id)and(nR==Dud[1937]or nR==Dud[1938]or nR==Dud[2344]or nR==Dud[2366])then
local oR=jb.share(mR.id)
if not P.str.share[mR.id]then
oR=math.min(oR,0.15)
end
local pR={}
for qR,rR in ipairs(hR)do
local sR=jb.relicWorth(mR.u,rR)*oR*100
if sR>0.01 then
table.insert(pR,{it=rR,w=sR})
end
end
table.sort(pR,function(tR,uR)
if tR.w~=uR.w then
return tR.w>uR.w
end
return tR.it.uuid<uR.it.uuid
end)
local vR,wR={},{}
for xR,yR in ipairs(pR)do
local zR=wR[yR.it.item_id]or 0
if#vR<6 and zR<((N.Items[yR.it.item_id]or{}).unique_equip and 1 or 2)then
wR[yR.it.item_id]=zR+1
table.insert(vR,yR)
end
end
if mR.u._equipped_relic then
local AR=false
for BR,CR in ipairs(vR)do
if CR.it.uuid==mR.u._equipped_relic then
AR=true
end
end
local DR=not AR and fR.inventory:get_item_by_uuid(mR.u._equipped_relic)
if DR then
table.insert(vR,{it=DR,w=jb.relicWorth(mR.u,DR)*oR*100})
end
end
table.insert(kR,{e=mR,share=oR,opts=vR})
end
