local ER,FR={},-1
local GR,HR,IR={},{},{}
local function JR(KR,LR)
if KR> #kR then
if LR>FR then
FR=LR
ER=table.clone(GR)
end
return
end
local MR=kR[KR]
GR[MR.e.uuid]=nil
JR(KR+1,LR)
for NR,OR in ipairs(MR.opts)do
local PR=(N.Items[OR.it.item_id]or{}).unique_equip
if not HR[OR.it.uuid]and not(PR and IR[OR.it.item_id])then
HR[OR.it.uuid]=true
if PR then
IR[OR.it.item_id]=true
end
GR[MR.e.uuid]=OR.it.uuid
JR(KR+1,LR+OR.w+(OR.it.uuid==MR.e.u._equipped_relic and 0.01 or 0))
GR[MR.e.uuid]=nil
HR[OR.it.uuid]=nil
if PR then
IR[OR.it.item_id]=nil
end
end
end
end
JR(1,0)
local QR,RR=0,{}
for SR,TR in ipairs(kR)do
local UR=TR.e.u._equipped_relic and fR.inventory:get_item_by_uuid(TR.e.u._equipped_relic)
local VR=UR and jb.relicWorth(TR.e.u,UR)*TR.share*100 or 0
QR=QR+VR
local WR=ER[TR.e.uuid]and fR.inventory:get_item_by_uuid(ER[TR.e.uuid])
local XR=WR and jb.relicWorth(TR.e.u,WR)*TR.share*100 or 0
table.insert(RR,string.format(Dud[2367],V.name(TR.e.id),UR and(N.Items[UR.item_id]or{}).name or Dud[1948],VR,WR and(N.Items[WR.item_id]or{}).name or Dud[1948],XR))
end
return ER,FR-QR,RR,kR
