function jb.finishWork()
local BV=U.now()
local CV=0
while F.alive and O.master and not P.holdLobby and not P.pauseAll and U.now()-BV<jb.WORK_MAX do
local DV,EV=jb.hasWork(true)
if not DV then
break
end
F.status(Dud[2421],Dud[2422]..tostring(DV))
if EV==Dud[2418]then
local FV,GV=pcall(jb.relicsApply,true)
if not(FV and GV)then
P.str.noWork.relic=os.time()+1800
end
else
jb.tick()
end
CV=CV+1
task.wait(4)
end
if CV>0 then
F.log(1,jb.LOG,string.format(Dud[2423],CV,math.floor(U.now()-BV)))
W._sigAt,W.lastScored=nil,nil
F.saveSoon()
end
end
function jb.tick()
if not O.team then
P.str.next=Dud[2424]
return
end
if P.str.reequip then
jb.reequip()
end
local HV
if ab.every(Dud[2425],60)or not P.str.acts then
HV=jb.plan()
else
HV=jb.acts
end
jb.acts=HV or jb.acts or{}
local IV=jb.nextAct(jb.acts)
if not IV then
local JV=jb.acts[1]
P.str.next=JV and(JV.text..Dud[2426]..tostring(JV.blocked))or Dud[2427]
return
end
if O.strDry then
P.str.next=Dud[2428]..IV.text..Dud[2429]
if P.str.dryLast~=IV.text then
P.str.dryLast=IV.text
F.log(1,jb.LOG,Dud[2430]..IV.text)
end
return
end
P.str.next=IV.text
local KV=jb.workSig()
local LV,MV=pcall(jb.run,IV)
if not LV then
