end
local NV=IV.kind==Dud[2388]and os.time()-(tonumber(O.fuseArmAt)or 0)<45
if jb.workSig()==KV and not NV then
P.str.noWork[IV.kind..Dud[1770]..tostring(IV.uuid)]=os.time()+1800
end
local OV=F.req.back[jb.REMOTE[IV.kind]or Dud[570]]
