fW=fW+1
gW[hW]=true
end
end
local jW,kW=F.request(Dud[1739],Dud[2446],bW.uuid)
task.wait(2)
local lW=dW.collection:get_unit_by_uuid(bW.uuid)
local mW=0
for nW,oW in pairs(dW.profile_data.collection.owned_units)do
if oW.unit_id==bW.to then
