if not gW[nW]then
if O.fuseXpUnit==bW.uuid then
O.fuseXpUnit,O.fuseXpId=nW,bW.to
F.saveSoon()
end
if O.fuseUnit==bW.uuid then
O.fuseUnit=nW
F.saveSoon()
end
end
end
end
if mW>fW then
local pW={}
for qW,rW in ipairs(bW.items or{})do
