end
local uW=string.format(Dud[2449],V.name(bW.from),V.name(bW.to),U.fmt(bW.scoreFrom or 0),U.fmt(bW.scoreTo or 0))
cb.add(Dud[2450]..uW,1,Dud[2451],(cW or Dud[2452])..(#pW>0 and(Dud[2453]..table.concat(pW,Dud[1755]))or Dud[570]))
F.log(1,Dud[2454],uW..Dud[2455]..(cW or Dud[2452])..(#pW>0 and(Dud[2453]..table.concat(pW,Dud[1755]))or Dud[570]))
W._sigAt=nil
pcall(gb.refresh)
return true,V.name(bW.to)..Dud[2456]
end
F.log(1,Dud[2454],Dud[2457]..V.name(bW.from)..Dud[2055]..tostring(kW)..Dud[2458]..tostring(lW and lW.unit_id))
return false,Dud[2459]..tostring(kW)..Dud[2029]
end
