if not VW or F.where~=Dud[1714]then
return false
end
if F.req.back.evobuy and U.now()<F.req.back.evobuy then
return false
end
local WW=(N.Items[VW.item]or{}).name or VW.item
local XW=gb.have(VW.item)
local YW,ZW=F.request(Dud[2466],Dud[1978],VW.item,Dud[1662],Dud[1979],Dud[1811])
local _W=U.now()
