function ab.autoEvolve()
if not O.autoEvolve or O.evolveUnit==Dud[570]then
return
end
local aX=N.session()
if not(aX and aX.collection:get_unit_by_uuid(O.evolveUnit))then
return ab.pickDone(Dud[2470],Dud[2464],Dud[2471],Dud[2472])
end
local bX
for cX,dX in ipairs(P.goals or{})do
if dX.pinned and dX.uuid==O.evolveUnit then
bX=dX
break
end
end
if not bX then
local eX=aX.collection:get_unit_by_uuid(O.evolveUnit)
local fX=N.Units[eX.unit_id]
if not(fX and fX.evolve and fX.evolve.evolve_unit)then
ab.pickDone(Dud[2470],Dud[2464],V.name(eX.unit_id)..Dud[2473],Dud[2472])
end
return
end
ab.pickNote.autoEvolve=nil
if not bX.ready and ab.evolveBuy(bX)then
for gX,hX in ipairs(P.goals or{})do
if hX.pinned and hX.uuid==O.evolveUnit then
bX=hX
break
end
end
end
if not bX.ready then
return
end
local iX={}
for jX,kX in ipairs(V.equipped())do
iX[kX.uuid]=true
end
local lX=ab.evoEats(bX,iX)
if lX then
ab.pickNote.autoEvolve=lX
return
end
if(ab.evoBlocked[bX.uuid]or 0)>=os.time()then
return
end
local mX,nX=ab.evolve(bX,Dud[2474])
if mX then
ab.pickDone(Dud[2470],Dud[2464],nX)
else
ab.evoBlocked[bX.uuid]=os.time()+3600
ab.pickNote.autoEvolve=nX
end
end
