function ab.fuseFuel(rX,sX)
local tX=N.session()
local uX={[rX.uuid]=true,[O.evolveUnit]=true,[O.fuseXpUnit]=true}
local vX={}
for wX,xX in ipairs(V.equipped())do
uX[xX.uuid]=true
end
for yX,zX in ipairs(P.savedTeam or{})do
uX[zX]=true
end
for AX,BX in ipairs(P.train and P.train.on and P.train.on.base or{})do
uX[BX]=true
end
for CX,DX in ipairs(P.goals or{})do
uX[DX.uuid]=true
for EX,FX in ipairs(DX.eats or{})do
vX[FX.id]=true
end
end
for GX,HX in ipairs(P.str and P.str.core or{})do
uX[HX]=true
end
local IX=gb.strongest(10)
local JX,KX={},0
for LX,MX in pairs(tX.profile_data.collection.owned_units)do
local NX=tX.collection:get_unit_by_uuid(LX)or MX
local OX,PX,QX=pcall(N.USC.is_unit_good_for_fusion,rX,NX)
if OX and PX and not(MX._locked or NX._locked)and not uX[LX]and not vX[NX.unit_id]and not(MX._equipped_relic or NX._equipped_relic)and not(MX.shiny or NX.shiny)and not V.trait(NX)and not(MX.further_modifiers and MX.further_modifiers.limit_break)then
local RX=gb.fodderOrder(NX.unit_id)
if RX and not IX[LX]then
local SX,TX=pcall(V.score,NX)
table.insert(JX,{uuid=LX,id=NX.unit_id,pts=tonumber(QX)or 1,sc=SX and TX or 0,order=RX})
KX=KX+(tonumber(QX)or 1)
end
end
end
table.sort(JX,function(UX,VX)
if UX.order~=VX.order then
return UX.order<VX.order
end
if UX.sc~=VX.sc then
return UX.sc<VX.sc
end
return UX.uuid<VX.uuid
end)
local WX,XX={},0
for YX,ZX in ipairs(JX)do
if XX>=sX then
break
end
table.insert(WX,ZX)
XX=XX+ZX.pts
end
return WX,XX,KX
end
