function eb.upgradeGain(nkb,okb,pkb,qkb,rkb,skb)
local tkb,ukb=okb[pkb],okb[pkb+1]
local vkb=(tkb.cd>0 and tkb.damage/tkb.cd or 0)
local wkb=(ukb.cd>0 and ukb.damage/ukb.cd or 0)*V.aoe(ukb.atk,ukb.range)/math.max(0.3,V.aoe(tkb.atk,tkb.range))
local xkb=vkb>0 and nkb*(wkb/vkb-1)or(skb or 0)
local ykb=okb[pkb+2]
if ykb and pkb+1<okb.max and ykb.cd>0 and ukb.cd>0 and vkb>0 then
local zkb=nkb*((ykb.damage/ykb.cd)/vkb-1)
local Akb=qkb+ykb.cost*rkb
if zkb/Akb>xkb/qkb then
xkb=xkb+(zkb/Akb*qkb-xkb)*0.5
end
end
local Bkb=(ukb.range or 0)>(tkb.range or 0)and(1+((ukb.range-tkb.range)/math.max(1,tkb.range)))or 1
return math.max(0,xkb)*Bkb
end
function eb.dpsFor(Ckb,Dkb)
if Dkb<=0 then
return 0
end
local Ekb={}
for Fkb,Gkb in ipairs(Ckb)do
if not Gkb.farm and Gkb.gain>0 then
table.insert(Ekb,Gkb)
end
end
table.sort(Ekb,function(Hkb,Ikb)
return Hkb.gain/Hkb.cost>Ikb.gain/Ikb.cost
end)
local Jkb,Kkb=0,0
for Lkb,Mkb in ipairs(Ekb)do
if Dkb<=0 then
