function bb.buildPath()
bb.samples={}
local fYb=N.PATH and N.PATH.PATH_CACHE and N.PATH.PATH_CACHE[workspace._BASES.pve]
if not fYb then
return
end
for gYb,hYb in pairs(fYb)do
if not(N.PATH.HIDDEN_MOCK_LANES and N.PATH.HIDDEN_MOCK_LANES[gYb.Name])then
local iYb={}
for jYb,kYb in ipairs(hYb.points or{})do
table.insert(iYb,kYb.part.Position)
end
local lYb=0
for mYb=2,#iYb do
lYb=lYb+(iYb[mYb]-iYb[mYb-1]).Magnitude
end
local nYb=0
for oYb=2,#iYb do
local pYb,qYb=iYb[oYb-1],iYb[oYb]
local rYb=(qYb-pYb).Magnitude
local sYb=math.max(1,math.floor(rYb/2))
for tYb=0,sYb-1 do
local uYb=pYb:Lerp(qYb,tYb/sYb)
table.insert(bb.samples,{pos=uYb,prog=(nYb+rYb*tYb/sYb)/math.max(1,lYb),lane=gYb.Name})
end
nYb=nYb+rYb
end
if iYb[#iYb]then
table.insert(bb.samples,{pos=iYb[#iYb],prog=1,lane=gYb.Name})
end
end
end
bb.laneCut,bb.laneWant,bb.laneFirst=nil,nil,nil
