if vYb and vYb>=1 and wYb and#wYb>vYb then
bb.laneWant=vYb
end
bb.laneTotal=wYb and#wYb or 1
bb.countLanes()
end
function bb.countLanes()
local xYb,yYb,zYb={},0,0
for AYb,BYb in ipairs(bb.samples)do
local CYb=tostring(BYb.lane)
if not xYb[CYb]then
yYb=yYb+1
end
xYb[CYb]=(xYb[CYb]or 0)+1
zYb=zYb+1
end
bb.laneCount={n=yYb,by=xYb,avg=yYb>0 and zYb/yYb or 1}
