local GYb,HYb={},0
for IYb,JYb in ipairs(workspace._UNITS:GetChildren())do
local KYb=JYb:FindFirstChild(Dud[1706])
if KYb and KYb:FindFirstChild(Dud[3378])and KYb.player.Value==nil and KYb:FindFirstChild(Dud[3379])and JYb:FindFirstChild(Dud[2649])then
local LYb=tostring(KYb.lane.Value)
if not GYb[LYb]then
GYb[LYb]=true
HYb=HYb+1
