if not Xac(Vac.id)or V.toggleOf(Vac.id)then
return nil
end
local Yac,Zac,_ac,abc=1,0,0,{}
for bbc,cbc in ipairs(bb.mine or{})do
local dbc=cbc._stats
local ebc=dbc.id.Value
if dbc:FindFirstChild(Dud[1810])and not V.isFarm(ebc)and not V.allyBuff(ebc)then
local fbc,gbc=U.flat(cbc:GetPivot().Position),dbc.range.Value
if Xac(ebc)and not V.toggleOf(ebc)then
_ac=_ac+1
table.insert(abc,{p=fbc,r=gbc})
else
for hbc,ibc in ipairs(bb.samples)do
if(U.flat(ibc.pos)-fbc).Magnitude<=gbc then
Yac,Zac=math.min(Yac,ibc.prog),math.max(Zac,ibc.prog)
end
end
end
end
end
if Zac<=Yac then
Yac,Zac=0.75,0.98
end
local jbc=(Wac or _ac)+1
local kbc=({Yac,Zac,(Yac+Zac)/2,Yac-(Zac-Yac)/2})[jbc]
if not kbc then
return nil
end
local lbc=V.range(Vac.u,0)*((bb.info and tonumber(bb.info.rangeScale))or 1)
local mbc={}
for nbc,obc in ipairs(bb.cands)do
local pbc,qbc,rbc=U.flat(obc),0,0
for sbc,tbc in ipairs(bb.samples)do
if(U.flat(tbc.pos)-pbc).Magnitude<=lbc then
rbc=rbc+1
if math.abs(tbc.prog-kbc)<=0.05 then
qbc=qbc+1
local ubc=U.flat(tbc.pos)
for vbc,wbc in ipairs(abc)do
if(ubc-wbc.p).Magnitude<=wbc.r then
qbc=qbc-0.5
break
end
end
end
end
end
if qbc>0 then
table.insert(mbc,{pos=obc,sc=qbc,cov=rbc})
end
if nbc%60==0 then
task.wait()
end
end
table.sort(mbc,function(xbc,ybc)
return xbc.sc>ybc.sc
end)
for zbc,Abc in ipairs(mbc)do
local Bbc=bb.valid(Abc.pos,Vac.data)
if Bbc then
F.log(1,Dud[3478],string.format(Dud[3516],V.name(Vac.id),bb.CONTROL_WORDS[jbc],math.floor(kbc*100+0.5)))
return Bbc,Abc.cov,kbc
end
if zbc%20==0 then
task.wait()
end
end
return nil
end
function bb.holdSpot(Cbc)
