local Kbc=Jbc.id.Value
if Jbc:FindFirstChild(Dud[1810])and not V.isFarm(Kbc)and not V.allyBuff(Kbc)and Kbc~=Cbc.id then
local Lbc,Mbc=pcall(bb.liveDps,Ibc,Kbc)
