return Xec.Magnitude>0.01 and Xec.Unit or Vector3 .new(0,0,-1)
end
function bb.place(Yec,Zec)
local _ec=V.isFarm(Yec.id)
local afc,bfc=bb.bestSpot(Yec,_ec or(bb.random and V.idol(Yec.id)),(bb.trainee~=nil and Yec.uuid==bb.trainee)or V.ENTRY[Yec.id]==true or(bb.studyEntry==true and Yec.id==bb.trialId))
if not afc then
