end
local cfc=bb.money()
local dfc,efc=F.request(Dud[3521],Dud[3522],Yec.uuid,N.Util.CFramePLV(afc,bb.lookAt(afc)))
if dfc and efc then
bb.spent=bb.spent+(Yec.data.cost or 0)
table.insert(bb.actions,string.format(Dud[3523],V.name(Yec.id)))
F.log(1,Dud[3478],string.format(Dud[3524],V.name(Yec.id),bb.spotKey(afc),bfc,Zec))
bb.placeLog=bb.placeLog or{}
table.insert(bb.placeLog,{t=math.floor(U.now()-(bb.startT or U.now())),w=bb.wave(),id=Yec.id,x=math.floor(afc.X),z=math.floor(afc.Z),cover=math.floor((bfc or 0)+0.5),why=tostring(Zec):sub(1,90)})
F.status(Dud[3472],string.format(Dud[3525],V.name(Yec.id),Zec))
bb.placedAt=bb.placedAt or{}
bb.placedAt[Yec.uuid]=(bb.placedAt[Yec.uuid]or 0)+1
return true
end
if cfc>=(Yec.data.cost or 0)and bb.random then
bb.placeFail=bb.placeFail or{}
bb.placeFail[Yec.uuid]=(bb.placeFail[Yec.uuid]or 0)+1
if bb.placeFail[Yec.uuid]>=2 then
bb.noSpot[Yec.uuid]=3
F.log(1,Dud[3478],string.format(Dud[3526],V.name(Yec.id),bb.fieldCount(),bb.FIELD_MAX))
end
end
if dfc and cfc>=(Yec.data.cost or 0)and not bb.random then
local ffc=bb.spotKey(afc)
bb.refused[ffc]=true
local gfc=bb.mapKey()
P.blocked[gfc]=P.blocked[gfc]or{}
if not bb.refusedRun[ffc]then
P.blocked[gfc][ffc]=(tonumber(P.blocked[gfc][ffc])or 0)+1
bb.refusedRun[ffc]=true
end
bb.refusals=(bb.refusals or 0)+1
bb.unitRefusals[Yec.uuid]=(bb.unitRefusals[Yec.uuid]or 0)+1
if bb.unitRefusals[Yec.uuid]>=3 then
local hfc=math.max(1,bb.count(Yec.uuid))
if P.caps[Yec.uuid]~=hfc then
P.caps[Yec.uuid]=hfc
F.log(1,Dud[3478],string.format(Dud[3527],V.name(Yec.id),hfc))
end
end
