for kfc,lfc in ipairs({workspace._UNITS,workspace:FindFirstChild(Dud[3529])})do
if lfc then
for mfc,nfc in ipairs(lfc:GetChildren())do
local ofc=nfc:FindFirstChild(Dud[1706])
if ofc and ofc:FindFirstChild(Dud[3518])and ofc.player.Value==M and ofc.uuid.Value==ifc then
jfc=jfc+1
end
end
end
end
return jfc
