function bb.measure()
local pfc,qfc=bb.calRun,bb.info
if not(pfc and qfc)then
return
end
pcall(bb.sampleHelpers)
local rfc=U.now()
local sfc=bb.wave()
local tfc=bb.money()
if not pfc.start and tfc>0 and#bb.mine==0 then
pfc.start=tfc
end
if sfc~=pfc.lastW then
if bb.trialId and sfc>0 then
bb.trialTrace=bb.trialTrace or{}
local ufc,vfc,wfc,xfc=0,{},0,0
for yfc,zfc in ipairs(bb.mine)do
local Afc=zfc._stats
if Afc.id.Value==bb.trialId then
ufc=ufc+1
table.insert(vfc,tostring(Afc.upgrade.Value))
elseif not V.isFarm(Afc.id.Value)then
xfc=xfc+1
end
end
pcall(bb.sampleHelpers,true)
for Bfc,Cfc in pairs(bb.ownDealt)do
if Cfc.id==bb.trialId then
wfc=wfc+Cfc.v
end
end
local Dfc=0
for Efc,Ffc in pairs(bb.helperDealt)do
if Ffc.owner==bb.trialId then
Dfc=Dfc+Ffc.v
end
end
table.insert(bb.trialTrace,string.format(Dud[3530],sfc,rfc-(bb.startT or rfc),tfc,table.concat(vfc,Dud[2354]),xfc,wfc+Dfc,#(bb.enemies or{}),bb.hpAliveRaw or 0,bb.waveMax[sfc-1]or 0,bb.teamDps or 0))
end
if pfc.lastW and pfc.lastW>0 and pfc.lastWT then
table.insert(pfc.waveSec,rfc-pfc.lastWT)
end
if pfc.paidT and sfc>0 and rfc-pfc.paidT<15 then
table.insert(pfc.skip,rfc-pfc.paidT)
end
pfc.paidT=nil
if sfc>0 then
pfc.alive[tostring(sfc)]=bb.hpAliveRaw or 0
end
pfc.lastW,pfc.lastWT=sfc,rfc
end
local Gfc=workspace:FindFirstChild(Dud[3531])
if Gfc and sfc>0 then
pfc.timer[tostring(sfc)]=math.max(pfc.timer[tostring(sfc)]or 0,tonumber(Gfc.Value)or 0)
end
local Hfc=tfc-(bb.lastMoneyR or tfc)
bb.lastMoneyR=tfc
bb.incomeLog=bb.incomeLog or{}
if Hfc>0 then
table.insert(bb.incomeLog,{t=rfc,y=Hfc})
end
while bb.incomeLog[1]and rfc-bb.incomeLog[1].t>30 do
table.remove(bb.incomeLog,1)
