local xjc=V.rows(wjc.id.Value)
local yjc=xjc and xjc[math.min(wjc.upgrade.Value,xjc.max)]
local zjc=yjc and yjc.atk and V.attackInfo(yjc.atk,yjc.range)
if zjc and((zjc.stun or 0)>0 or(zjc.slowTime or 0)>0)then
tjc=tjc+1
end
end
local Ajc,Bjc=fb.mask(bb.info.map,V.range(qjc.u,0)*(bb.info.rangeScale or 1)),0
for Cjc=1,fb.BINS do
if Ajc[Cjc]then
Bjc=Bjc+1
end
end
local Djc=bb.depth and bb.depth.units>0 and bb.depth.covEnd or 1
local Ejc=(V.airFrom(qjc.id)==0)and 1 or(1-(1-N.FLY_GROUND)*math.min(1,bb.info.flyChance or 0))
return eb.holdGain(sjc,bb.teamDps or 0,Bjc/(math.max(0.1,Djc)*fb.BINS)*Ejc,tjc)
end
function bb.buffGain(Fjc)
local Gjc=V.allyBuff(Fjc.id)
if not Gjc then
return 0
end
local Hjc=bb.buffShort(Gjc)
local Ijc=P.stack[Gjc.attack]
local Jjc=Ijc and Ijc.stacks and(Ijc.cap or 1)or nil
local Kjc,Ljc=pcall(V.range,Fjc.u,0)
Ljc=(Kjc and tonumber(Ljc)or 15)*((bb.info and tonumber(bb.info.rangeScale))or 1)
local Mjc=Jjc and O.community and tonumber(Gjc.time)and tonumber(Gjc.cd)
local function Njc(Ojc,Pjc)
local Qjc=math.floor(Ojc*Gjc.time/math.max(1,Gjc.cd)+0.001)
return math.min(Jjc,(1+Pjc)^Qjc-1)
end
local Rjc=0
for Sjc,Tjc in ipairs(Hjc)do
local Ujc=0
for Vjc,Wjc in ipairs(Hjc)do
if(Wjc.pos-Tjc.pos).Magnitude<=Ljc then
local Xjc=Gjc.types[Wjc.base]
local Yjc=Xjc*Gjc.uptime
if Mjc then
local Zjc,_jc=Njc(Wjc.n,Xjc),Wjc.n+1
while _jc<Wjc.n+6 and Njc(_jc,Xjc)<=Zjc+0.001 do
_jc=_jc+1
end
Yjc=math.max(0,(Njc(_jc,Xjc)-Zjc)/(_jc-Wjc.n))
elseif Jjc then
Yjc=math.max(0,math.min(Jjc,(Wjc.n+1)*Xjc*Gjc.uptime)-math.min(Jjc,Wjc.n*Xjc*Gjc.uptime))
end
Ujc=Ujc+Wjc.dps*Yjc
end
end
Rjc=math.max(Rjc,Ujc)
end
return Rjc*(Mjc and 1 or 0.7)
end
function bb.buffWanted(akc)
