table.insert(goc,loc)
if moc:FindFirstChild(Dud[3534])and moc.target.Value~=nil then
local qoc=(foc[loc]or 0)>=Rnc
if Ync.ally then
qoc=bb.buffOn(moc,poc)or(foc[loc]or 0)-eoc+2>=Rnc
end
