else
hoc=hoc+1
end
end
end
end
end
local roc=P.stack[Vnc.Value]
if roc and not roc.stacks and os.time()-(roc.at or 0)>3*86400 then
roc=nil
end
local soc=Ync.ally and ioc>0 and bb.buffLevel(Ync.ally.types)or 0
local toc=ioc>0 and Ync.ally and O.community and soc>0 and((roc==nil and joc-Rnc>5)or(roc and roc.stacks and soc<(roc.cap or 1)-0.02))
if hoc>ioc or toc then
aoc,boc=true,string.format(Dud[3606],hoc+ioc)
if toc and roc==nil then
