if qpc and type(rpc)==Dud[1645]and rpc[ppc]then
bb.prioAt[fpc]=U.now()
local spc=F.request(Dud[3623],Dud[3624],fpc,ppc)
if spc then
F.status(Dud[3628],string.format(Dud[3629],V.name(hpc),ppc,ppc==Dud[1630]and Dud[3630]or(opc and Dud[3631]or Dud[3632])))
F.log(2,Dud[3625],V.name(hpc)..Dud[2582]..ppc)
