kb.CARD_PICKS={Dud[571],Dud[1657],Dud[1930],Dud[1926]}
function kb.cardPearls(tpc,upc)
local vpc=kb.pearlsFrom((tonumber(upc)or 0)+1,50)
local wpc=0
for xpc,ypc in pairs(type(tpc)==Dud[1645]and type(tpc.effects)==Dud[1645]and tpc.effects or{})do
if type(ypc)==Dud[1645]and ypc.type==Dud[1910]then
wpc=wpc+math.abs(tonumber(ypc.amount)or 0)*vpc
end
end
return wpc
end
function kb.cardLuck(zpc)
local Apc=0
for Bpc,Cpc in pairs(type(zpc)==Dud[1645]and type(zpc.effects)==Dud[1645]and zpc.effects or{})do
if type(Cpc)==Dud[1645]and Cpc.type==Dud[1913]then
Apc=Apc+(tonumber(Cpc.amount)or 0)
end
end
return Apc
end
function bb.huntChoose(Dpc,Epc)
bb.fhP=bb.fhP or 1
local Fpc=kb.floor()
local Gpc=(bb.pressure or 0)>=O.safeReach or(bb.depth and bb.depth.leak)
local Hpc=kb.weatherStrength(kb.weatherNow())
local Ipc=table.find(kb.CARD_PICKS,O.huntCards)and O.huntCards or Dud[1926]
local Jpc,Kpc,Lpc,Mpc
local Npc={}
for Opc,Ppc in pairs(Dpc)do
local Qpc,Rpc=1,{}
for Spc,Tpc in pairs(type(Ppc)==Dud[1645]and Ppc.effects or{})do
if type(Tpc)==Dud[1645]then
local Upc=bb.rogueEffect(Tpc)
Qpc=Qpc*Upc
table.insert(Rpc,bb.effectText(Tpc))
end
end
if type(Ppc)==Dud[1645]and Ppc.weather then
Qpc=Qpc*kb.weatherStrength(Ppc.weather)/math.max(0.05,Hpc)
end
local Vpc=type(Ppc)==Dud[1645]and kb.cardGems(Ppc,Epc)or 0
local Wpc=Qpc>=1 or(bb.fhP*Qpc>=Fpc and not Gpc)
local Xpc=math.log(math.max(0.05,Qpc))
local Ypc=Xpc*kb.STRENGTH_GEMS+(Wpc and Vpc or-1000)
local Zpc=kb.cardLuck(Ppc)
if Ipc==Dud[571]and Wpc and Zpc>0 then
Ypc=2e6+Zpc*1e4+Vpc
elseif Ipc==Dud[1657]and Wpc then
Ypc=1e6+kb.cardPearls(Ppc,Epc)*10+Vpc+Xpc
elseif Ipc==Dud[1930]then
Ypc=Xpc*1e6+Vpc
end
if not Kpc or Ypc>Kpc then
Jpc,Kpc,Lpc,Mpc=Opc,Ypc,Qpc,Vpc
end
table.insert(Npc,string.format(Dud[3633],tostring(Opc),tostring(type(Ppc)==Dud[1645]and Ppc.title or Dud[1917]),(type(Ppc)==Dud[1645]and Ppc.weather)and(Dud[2055]..tostring(Ppc.weather)..Dud[2029])or Dud[570],tostring(type(Ppc)==Dud[1645]and Ppc.option_type or Dud[1917]),Qpc,math.floor(Vpc+0.5),table.concat(Rpc,Dud[2000])))
end
return Jpc,Lpc,Mpc,Npc,Fpc,Gpc,Ipc
end
function bb.huntPick(_pc)
