if iqc then
kb.write(Dud[3634],string.format(Dud[3635],os.date(Dud[2872]),aqc,tostring(bb.ld.map),tostring(kb.weatherNow()),jqc))
end
local kqc=F.request(Dud[3636],Dud[3637],bqc)
local lqc=bqc and kb.cardLuck(_pc[bqc])or 0
F.log(1,Dud[3638],string.format(Dud[3639],aqc,tostring(bqc),tostring(hqc),math.floor((dqc or 0)+0.5),lqc>0 and string.format(Dud[3640],lqc)or Dud[570],bb.fhP,fqc,gqc and Dud[3641]or Dud[570],table.concat(eqc,Dud[3642])))
return kqc
end
function bb.huntRecord(mqc,nqc,oqc,pqc)
