function bb.rogueShare(_qc)
if not _qc then
return 0.5
end
local arc=tostring(_qc):gsub(Dud[3101],Dud[570])
local brc,crc=0,0
for drc,erc in ipairs(bb.mine or{})do
local frc=erc._stats.id.Value
if not V.isFarm(frc)then
local grc,hrc=pcall(bb.liveDps,erc,frc)
hrc=grc and hrc or 0
local irc=V.types(frc)
brc=brc+hrc
if irc[arc]or irc[arc..Dud[3213]]then
crc=crc+hrc
end
end
end
local jrc=0
for krc,lrc in ipairs(bb.mine or{})do
if not V.isFarm(lrc._stats.id.Value)then
jrc=jrc+1
end
end
local mrc=jrc/(jrc+4)
return mrc*(brc>0 and crc/brc or 0.5)+(1-mrc)*0.5
end
function bb.resistOf(nrc)
local orc=V.types(nrc)
local prc=0
for qrc,rrc in pairs(bb.fhResist or{})do
local trc=tostring(qrc):gsub(Dud[3101],Dud[570])
if orc[trc]or orc[trc..Dud[3213]]then
prc=math.max(prc,rrc/100)
end
end
return math.min(0.95,prc)
end
function bb.rogueEffect(urc)
local vrc,wrc,xrc=urc.type,tonumber(urc.amount)or 0,tostring(urc.stat or Dud[570])
if vrc==Dud[1910]then
return 1,math.abs(wrc)
end
if vrc==Dud[3216]or vrc==Dud[3221]or vrc==Dud[3217]then
if xrc==Dud[1807]then
return math.max(0.3,1+wrc),0
end
if xrc==Dud[1810]then
return math.max(0.5,1+wrc/2),0
end
if xrc:find(Dud[2134])then
return 1/math.max(0.3,1+wrc),0
end
return 1,0
end
if vrc==Dud[3658]then
if xrc==Dud[1807]then
return math.max(0.3,wrc),0
end
if xrc==Dud[1810]then
return math.max(0.5,1+(wrc-1)/2),0
end
if xrc:find(Dud[2134])then
return 1/math.max(0.3,wrc),0
end
return 1,0
end
if vrc==Dud[3223]then
return 1+wrc/3,0
end
if vrc==Dud[3229]then
return 1/math.max(0.3,1+wrc),0
end
if vrc==Dud[3659]then
return math.max(0.2,1-bb.rogueShare(urc.damage_type)*(1-100/(100+wrc))),0
end
if vrc==Dud[3660]then
return 1+bb.rogueShare(urc.damage_type)*wrc,0
end
if vrc==Dud[3661]then
return math.max(0.5,1-wrc*0.5),0
end
if vrc==Dud[3662]then
return math.max(0.5,1-wrc*0.2),0
end
if vrc==Dud[3663]then
return 1+wrc*0.1,0
end
if vrc==Dud[3664]then
return 1/math.max(0.3,1+wrc*0.5),0
end
if vrc==Dud[3665]then
return math.max(0.5,1-wrc*0.1),0
end
if vrc==Dud[3224]then
return 1/math.max(0.3,1+wrc),0
end
if vrc==Dud[3230]then
return math.max(0.3,1-wrc*20),0
end
if vrc==Dud[3231]then
return math.max(0.5,1-wrc*0.03),0
end
if vrc==Dud[3666]then
return 0.95,0
end
if vrc==Dud[3232]then
return math.max(0.5,1-wrc),0
end
if vrc==Dud[3667]then
return 1+math.min(0.3,wrc/40000),0
end
if vrc==Dud[3225]then
return 1/math.max(0.3,1+wrc/2),0
end
if vrc==Dud[3668]then
return 0.8,0
end
if vrc==Dud[3669]then
local yrc=math.max(1,math.abs(wrc))*math.max(1,math.abs(tonumber(urc.tier)or 1))
