function bb.learn()
local Arc=bb.calRun and bb.calRun.potBy
if type(Arc)~=Dud[1645]then
return
end
pcall(bb.sampleHelpers,true)
local Brc={}
for Crc,Drc in pairs(bb.ownDealt or{})do
if not V.isFarm(Drc.id)then
Brc[Drc.id]=(Brc[Drc.id]or 0)+(tonumber(Drc.v)or 0)
end
end
for Erc,Frc in pairs(bb.helperDealt or{})do
if Frc.owner and V.SUMMONER[Frc.owner]then
Brc[Frc.owner]=(Brc[Frc.owner]or 0)+(tonumber(Frc.v)or 0)
end
end
local Grc,Hrc=0,0
for Irc,Jrc in pairs(Arc)do
if Jrc>0 then
Grc=Grc+(Brc[Irc]or 0)
Hrc=Hrc+Jrc
end
end
if Grc<=0 or Hrc<=0 then
return
end
local Krc=Grc/Hrc
bb.lastEff={}
for Lrc,Mrc in pairs(Arc)do
if Mrc>0 and Mrc/Hrc>0.02 then
local Nrc=P.learn[Lrc]or{eff=1,n=0,v=3}
if(tonumber(Nrc.v)or 0)<3 then
Nrc.eff,Nrc.v=(tonumber(Nrc.eff)or 1)*V.effRescale(Lrc),3
end
local Orc=math.max(0.02,0.25*math.sqrt(30/(30+Nrc.n)))
local Prc=U.clamp(((Brc[Lrc]or 0)/Mrc)/Krc,0.2,6)
bb.lastEff[Lrc]=math.floor(Prc*1000+0.5)/1000
Nrc.eff=Nrc.eff+(Prc-Nrc.eff)*Orc
Nrc.n=Nrc.n+1
P.learn[Lrc]=Nrc
end
end
local Qrc=V.mapKey((bb.info and bb.info.map)or(bb.ld and bb.ld.map),(bb.info and bb.info.mapSig)or V.mapSig(bb.ld))
if Qrc and next(bb.lastEff)then
P.mapLearn=type(P.mapLearn)==Dud[1645]and P.mapLearn or{}
local Rrc=type(P.mapLearn[Qrc])==Dud[1645]and P.mapLearn[Qrc]or{}
for Src,Trc in pairs(bb.lastEff)do
local Urc=type(Rrc[Src])==Dud[1645]and Rrc[Src]or{eff=Trc,n=0}
local Vrc=math.max(0.1,0.5*math.sqrt(4/(4+(tonumber(Urc.n)or 0))))
Urc.eff=(tonumber(Urc.n)or 0)==0 and Trc or((tonumber(Urc.eff)or Trc)+(Trc-(tonumber(Urc.eff)or Trc))*Vrc)
Urc.n=(tonumber(Urc.n)or 0)+1
Rrc[Src]=Urc
end
Rrc._at=os.time()
P.mapLearn[Qrc]=Rrc
if U.count(P.mapLearn)>80 then
local Wrc,Xrc
for Yrc,Zrc in pairs(P.mapLearn)do
if not Xrc or(tonumber(Zrc._at)or 0)<Xrc then
Wrc,Xrc=Yrc,tonumber(Zrc._at)or 0
end
end
P.mapLearn[Wrc]=nil
end
end
end
function bb.randomTeam()
local _rc=N.session()
local asc=_rc and _rc.collection.temporary_units or{}
local bsc,csc={},{}
local function dsc(esc,fsc,gsc)
local hsc=esc and asc[esc]
if hsc and N.Units[hsc.unit_id]and not csc[esc]then
csc[esc]=true
table.insert(bsc,{slot=gsc or 99,uuid=esc,u=hsc,id=hsc.unit_id,data=N.Units[hsc.unit_id],hand=fsc})
end
end
for isc,jsc in pairs(_rc and _rc.override_equipped_units or{})do
dsc(jsc,true,tonumber(isc))
end
for ksc,lsc in ipairs(bb.mine or{})do
local msc=lsc._stats
dsc(msc:FindFirstChild(Dud[3518])and msc.uuid.Value,false)
end
table.sort(bsc,function(nsc,osc)
return nsc.slot<osc.slot
end)
return bsc
end
function bb.fhSnap()
local psc,qsc=nil,nil
pcall(function()
for rsc,ssc in ipairs(workspace._BASES:GetDescendants())do
if ssc:IsA(Dud[3400])then
psc,qsc=ssc.Health,ssc.MaxHealth
break
end
end
end)
local tsc=psc and qsc and qsc>0 and math.floor(psc/qsc*100)or-1
local usc,vsc,wsc=0,{},{}
for xsc,ysc in ipairs(bb.enemies or{})do
if(ysc.prog or 0)>0.8 then
usc=usc+1
vsc[tostring(ysc.m)]=(vsc[tostring(ysc.m)]or 0)+1
end
wsc[tostring(ysc.m)]=(wsc[tostring(ysc.m)]or 0)+1
end
if not next(vsc)then
vsc=wsc
end
local zsc=0
for Asc,Bsc in ipairs(bb.mine or{})do
local Csc,Dsc=pcall(bb.liveDps,Bsc,Bsc._stats.id.Value)
if Csc and Dsc then
zsc=zsc+Dsc
end
end
bb.fhWaves=bb.fhWaves or{}
