for Fsc,Gsc in ipairs(bb.enemies or{})do
if Gsc.fly then
Esc=Esc+1
end
end
table.insert(bb.fhWaves,string.format(Dud[3672],bb.wave(),tsc,#(bb.enemies or{}),usc,U.fmt(zsc),bb.fieldCount(),bb.fhMult or 1,U.fmt(bb.money()),math.floor(bb.airShare()*100+0.5),Esc))
if tsc>=0 and bb.fhLastPct and tsc<bb.fhLastPct and not bb.fhLeak then
local Hsc={}
for Isc,Jsc in pairs(vsc)do
table.insert(Hsc,V.name(Isc)..Dud[3673]..Jsc)
end
bb.fhLeak=string.format(Dud[3674],bb.wave(),bb.fhLastPct,tsc,#Hsc>0 and table.concat(Hsc,Dud[1755])or Dud[3285])
F.log(1,Dud[2036],Dud[3675]..bb.fhLeak)
end
bb.fhLastPct=tsc
end
function bb.fhRecord(Ksc,Lsc)
