for Osc,Psc in ipairs(bb.mine or{})do
local Qsc=Psc._stats
local Rsc=Qsc:FindFirstChild(Dud[3533])and tonumber(Qsc.total_damage.Value)or 0
local Ssc=Qsc.id.Value
if Rsc>0 then
Msc[Ssc]=(Msc[Ssc]or 0)+Rsc
Nsc=Nsc+Rsc
end
end
local Tsc={}
for Usc,Vsc in pairs(Msc)do
local Wsc=Nsc>0 and Vsc/Nsc or 0
local Xsc=P.fh.units[Usc]or{n=0,share=0}
Xsc.share=(Xsc.share*Xsc.n+Wsc)/(Xsc.n+1)
Xsc.n=Xsc.n+1
P.fh.units[Usc]=Xsc
table.insert(Tsc,{id=Usc,share=Wsc})
