table.insert(P.fh.runs,1,{at=os.time(),wave=bb.wave(),won=Lsc or nil,coins=Ksc,top=_sc,mult=bb.fhMult or 1,discards=bb.discards,strength=bb.fhP,floor=btc,effects=bb.fhEffects,picks=bb.fhPicks,leak=bb.fhLeak,waves=bb.fhWaves})
while#P.fh.runs>20 do
table.remove(P.fh.runs)
