return string.format(Dud[3685]..Dud[3686]..Dud[3687],#etc,stc,ftc/ #etc,math.floor(gtc/ #etc+0.5),tostring(vtc.wave),tonumber(vtc.mult)or 1,tonumber(vtc.strength)or 1,vtc.leak and(Dud[3688]..vtc.leak)or Dud[570],table.concat(vtc.top or{},Dud[1755]),tonumber(P.fh.pmin)or 1,#otc>0 and table.concat(otc,Dud[1874])or Dud[3689],qtc,ytc)
end
function bb.cardDps(Ctc)
local Dtc,Etc=pcall(V.dps,Ctc.u,0,bb.mod)
Etc=Dtc and tonumber(Etc)or 0
if Etc>0 or V.isFarm(Ctc.id)or V.idol(Ctc.id)or V.allyBuff(Ctc.id)then
return Etc
end
local Ftc=table.clone(bb.cardVals or{})
if#Ftc==0 then
return 1000
end
table.sort(Ftc)
return Ftc[math.max(1,math.ceil(#Ftc*0.6))]
end
function bb.cardValue(Gtc)
if V.isFarm(Gtc.id)then
return 0
end
if V.idol(Gtc.id)then
return(bb.teamDps or 0)*bb.idolStep()*3
end
local Htc=V.allyBuff(Gtc.id)and bb.buffGain(Gtc)or bb.cardDps(Gtc)
return Htc*(1+2*bb.carry(Gtc.id))*(1-bb.resistOf(Gtc.id))*bb.airNeed(Gtc.id)*(bb.mergeIds[Gtc.id]and 2 or 1)
end
function bb.flyMode()
if bb.random or bb.flyerSeen then
return true
end
if bb.kind==Dud[1665]then
if bb._curseFly==nil then
local Itc,Jtc=pcall(ib.items,ib.data())
bb._curseFly=Itc and(Jtc._curse_fly or 0)>0 or false
end
return bb._curseFly
end
return false
end
function bb.shieldNow()
local Ktc=bb.wave()
if bb._shieldW~=Ktc then
bb._shieldW,bb._shieldS,bb._shieldH=Ktc,0,1
local Ltc,Mtc=pcall(fb.wave,bb.info,math.max(1,Ktc),true)
if bb.info and Ltc and#Mtc>0 then
local Ntc,Otc=0,0
for Ptc,Qtc in ipairs(Mtc)do
Ntc,Otc=Ntc+(Qtc.sh or 0),Otc+Qtc.hp
end
bb._shieldS,bb._shieldH=Ntc/ #Mtc,Otc/ #Mtc
end
end
return bb._shieldS,bb._shieldH
end
function bb.shieldOf(Rtc,Stc)
local Ttc,Utc=bb.shieldNow()
if Ttc<=0 or not Stc then
return Rtc
end
local Vtc=V.attackInfo(Stc.atk,Stc.range)
return eb.shieldDps(Rtc,tonumber(Stc.cd)or 2,Vtc.n,Ttc,Utc,bb.info and bb.info.eff,Vtc.hits)
end
function bb.shieldWork(Wtc,Xtc)
local Ytc,Ztc=bb.shieldNow()
if Ytc<=0 or not Xtc or not bb.info then
return 0
end
local _tc,auc=0,0
for buc,cuc in ipairs(bb.team or{})do
local duc=V.rows(cuc.id)
duc=duc and duc[0]
if duc and not V.isFarm(cuc.id)then
_tc=math.max(_tc,V.dps(cuc.u,0,bb.mod)*(tonumber(duc.cd)or 2)/math.max(1,V.attackInfo(duc.atk,duc.range).n))
end
end
for euc,fuc in ipairs(bb.mine or{})do
local guc=fuc._stats.id.Value
local huc=V.rows(guc)
local iuc=huc and huc[fuc._stats.upgrade and fuc._stats.upgrade.Value or 0]
if iuc and not V.isFarm(guc)and not V.allyBuff(guc)then
local juc=V.attackInfo(iuc.atk,iuc.range)
auc=auc+juc.n*juc.hits/math.max(0.3,tonumber(iuc.cd)or 2)
end
end
local kuc,luc=pcall(fb.wave,bb.info,math.max(1,bb.wave()),true)
local muc=V.attackInfo(Xtc.atk,Xtc.range)
return eb.shieldWork(muc.n,tonumber(Xtc.cd)or 2,auc,Ytc,kuc and#luc or 1,bb.info.waveSec,_tc*(bb.info.eff or 1),Ztc,muc.hits)
end
function bb.teamShield()
if bb._shieldAt and U.now()-bb._shieldAt<2 then
return bb._shieldTeam
end
local nuc,ouc=0,0
for puc,quc in ipairs(bb.mine or{})do
local ruc=quc._stats.id.Value
if not V.isFarm(ruc)and quc._stats:FindFirstChild(Dud[1734])then
local suc=V.rows(ruc)
local tuc,uuc=pcall(bb.liveDps,quc,ruc)
if tuc and suc then
nuc=nuc+uuc
ouc=ouc+bb.shieldOf(uuc,suc[quc._stats.upgrade.Value])
end
end
end
bb._shieldTeam,bb._shieldAt=nuc>0 and math.max(0.05,ouc/nuc)or 1,U.now()
return bb._shieldTeam
end
function bb.airLow()
if not bb.flyMode()then
return false
end
if ab.every(Dud[3690],1)or not bb.airShareNow then
bb.airShareNow=bb.airShare()
end
return bb.airShareNow<0.5
end
function bb.airWeight(vuc)
if not(vuc and bb.flyMode())then
return 1
end
return bb.airLow()and 2.5 or 1.5
end
function bb.reach(wuc)
if not bb.reachAt or U.now()-bb.reachAt>5 then
local xuc,yuc=0,0
for zuc,Auc in ipairs(bb.mine or{})do
local Buc=Auc._stats
if not V.isFarm(Buc.id.Value)and Buc:FindFirstChild(Dud[1810])then
xuc,yuc=xuc+bb.cover(Auc:GetPivot().Position,Buc.range.Value),yuc+1
end
end
bb.reachAvg,bb.reachAt=yuc>0 and xuc/yuc or 0,U.now()
end
local Cuc=wuc._stats
if(bb.reachAvg or 0)<=0 or not Cuc:FindFirstChild(Dud[1810])then
return 1
end
local Duc=bb.reachCache[wuc]
if Duc and U.now()-Duc.t<5 then
return Duc.v
end
local Euc=U.clamp(bb.cover(wuc:GetPivot().Position,Cuc.range.Value)/bb.reachAvg,0.4,1.6)
bb.reachCache[wuc]={v=Euc,t=U.now()}
return Euc
end
bb.reachCache=setmetatable({},{__mode=Dud[1859]})
function bb.airNeed(Fuc)
local Guc=V.airFrom(Fuc)
if Guc==0 then
return bb.airWeight(true)
end
if Guc then
return 1+(bb.airWeight(true)-1)*0.4
end
return 1
end
function bb.airBoost(Huc)
if bb.canAir(Huc)then
return bb.airWeight(true)
end
local Iuc=V.airFrom(Huc._stats.id.Value)
if not Iuc then
return 1
end
return 1+(bb.airWeight(true)-1)*math.min(1,(Huc._stats.upgrade.Value+1)/math.max(1,Iuc))
end
bb.cardSeen,bb.cardVals={},{}
function bb.fish()
if not bb.random then
return
end
local Juc={}
for Kuc,Luc in ipairs(bb.team)do
if Luc.hand then
table.insert(Juc,Luc)
if not bb.cardSeen[Luc.uuid]then
bb.cardSeen[Luc.uuid]=U.now()
if not V.isFarm(Luc.id)and not V.idol(Luc.id)then
table.insert(bb.cardVals,bb.cardValue(Luc))
end
end
end
end
if#bb.cardVals<8 or not ab.every(Dud[3691],5)then
return
end
local Muc=table.clone(bb.cardVals)
table.sort(Muc)
local Nuc=Muc[math.max(1,math.ceil(#Muc*0.6))]
local Ouc=0
for Puc,Quc in ipairs(bb.mine or{})do
if V.isFarm(Quc._stats.id.Value)then
Ouc=Ouc+1
end
end
local Ruc=bb.fieldCount()<16
local Suc=false
for Tuc,Uuc in ipairs(Juc)do
local Vuc=V.isFarm(Uuc.id)and bb.wave()<12 and Ouc<3 and not Suc
if Vuc then
Suc=true
end
local Wuc=bb.roomPlan and bb.roomPlan.name==V.name(Uuc.id)
local Xuc=(bb.noSpot[Uuc.uuid]or 0)>=3
local Yuc=not Xuc and(Vuc or Wuc or V.idol(Uuc.id)or bb.mergeIds[Uuc.id])
local Zuc=U.now()-(tonumber(bb.cardSeen[Uuc.uuid])or U.now())>60
if Xuc or(not Yuc and bb.cardValue(Uuc)<Nuc*((Ruc and not Zuc)and 0.25 or 1))then
if bb.discardCard(Uuc)then
F.log(2,Dud[3478],string.format(Dud[3692],V.name(Uuc.id),Xuc and Dud[3693]or(Dud[3694]..U.fmt(bb.cardValue(Uuc))..Dud[3695]..U.fmt(Nuc))))
bb.discards=(bb.discards or 0)+1
end
return
end
end
end
function bb.discardCard(_uc)
local avc=tostring(_uc.slot)
local bvc=N.session().override_equipped_units or{}
if bvc[avc]~=_uc.uuid then
return false
end
if not F.request(Dud[3696],Dud[3697],avc)then
return false
end
task.wait(0.3)
local cvc=(N.session().override_equipped_units or{})[avc]~=_uc.uuid
if not cvc and ab.every(Dud[3698],30)then
F.log(1,Dud[3478],Dud[3699]..V.name(_uc.id))
end
return cvc
end
