function bb.summonWorth()
if bb.summonAvg==nil then
local nvc,ovc,pvc=0,0,0
for qvc,rvc in ipairs(V.equipped())do
local tvc,uvc=pcall(V.dps,rvc.u,0,bb.mod)
nvc,ovc,pvc=nvc+((not V.isFarm(rvc.id)and tvc and uvc)or 0),ovc+1,pvc+(rvc.data.cost or 0)
end
bb.summonAvg,bb.summonCost=ovc>0 and nvc/ovc or 0,ovc>0 and pvc/ovc or 0
end
local vvc=bb.bestRate or 0
return vvc<=0 or bb.summonAvg*2>=vvc*(10000+bb.summonCost)
end
