if Wvc and Vvc.Visible then
local Xvc=0
for Yvc,Zvc in ipairs({Wvc.Activated,Wvc.MouseButton1Click,Wvc.MouseButton1Down})do
for _vc,awc in ipairs(getconnections(Zvc))do
if pcall(function()
awc:Fire()
end)then
Xvc=Xvc+1
end
