end
local Jxc=Gxc.base/Ixc
local Kxc,Lxc=0,0
local Mxc,Nxc=Fxc.foes or{},Gxc.foes or{}
for Oxc,Pxc in pairs(Nxc)do
if Pxc.prog>=bb.BASE_END then
Kxc=Kxc+Pxc.hp
local Qxc=Mxc[Oxc]
if Qxc then
Lxc=Lxc+math.max(0,Qxc.hp-Pxc.hp)
end
end
end
for Rxc,Sxc in pairs(Mxc)do
if Sxc.prog>=bb.BASE_END and not Nxc[Rxc]then
Lxc=Lxc+Sxc.hp
end
end
if Kxc<=0 then
