if Szc==Dud[3729]then
Qzc=true
elseif Szc==Dud[3767]then
bb.cloneCard=true
end
end
local Tzc={}
local Uzc=P.fh.noMerge or{}
for Vzc,Wzc in ipairs(bb.mine or{})do
local Xzc=Wzc._stats
local Yzc=Xzc.id.Value
if not V.isFarm(Yzc)and not V.allyBuff(Yzc)and not V.idol(Yzc)and Xzc:FindFirstChild(Dud[3768])and(Uzc[Yzc]or 0)<2 then
local Zzc,_zc=pcall(bb.liveDps,Wzc,Yzc)
Tzc[Yzc]=Tzc[Yzc]or{}
table.insert(Tzc[Yzc],{m=Wzc,lvl=Xzc.upgrade.Value,max=Xzc.max_upgrade.Value,dps=Zzc and _zc or 0})
end
end
local aAc={}
for bAc,cAc in ipairs(bb.team or{})do
if cAc.hand then
aAc[cAc.id]=true
end
end
local dAc={}
for eAc,fAc in pairs(Tzc)do
table.sort(fAc,function(gAc,hAc)
if gAc.dps~=hAc.dps then
return gAc.dps>hAc.dps
end
return gAc.lvl>hAc.lvl
end)
table.insert(dAc,{id=eAc,dps=fAc[1].dps*bb.airBoost(fAc[1].m)*bb.reach(fAc[1].m)})
end
table.sort(dAc,function(iAc,jAc)
return iAc.dps>jAc.dps
end)
for kAc=1,math.min(3,#dAc)do
bb.mergeIds[dAc[kAc].id]=true
end
local lAc
for mAc,nAc in pairs(Tzc)do
local oAc=table.clone(nAc)
table.sort(oAc,function(pAc,qAc)
if pAc.lvl~=qAc.lvl then
return pAc.lvl<qAc.lvl
end
return pAc.dps<qAc.dps
end)
for rAc,sAc in ipairs(oAc)do
if sAc.m==bb.freshM and rAc>1 then
table.remove(oAc,rAc)
table.insert(oAc,1,sAc)
break
end
end
local tAc,uAc,vAc,wAc
for xAc,yAc in ipairs(oAc)do
local zAc,AAc=U.flat(yAc.m:GetPivot().Position),yAc.m._stats.range.Value
local BAc,CAc,DAc=0,0,nil
for EAc,FAc in ipairs(nAc)do
if FAc~=yAc and(U.flat(FAc.m:GetPivot().Position)-zAc).Magnitude<=AAc then
BAc,CAc=BAc+FAc.dps,CAc+1
if not DAc or FAc.dps>DAc.dps then
DAc=FAc
end
end
end
if CAc>0 then
tAc,uAc,vAc,wAc=yAc,BAc,CAc,DAc
break
end
end
wAc=wAc or nAc[1]
local GAc=wAc.dps*bb.airBoost(wAc.m)*bb.reach(wAc.m)*(mAc==bb.planId and 2 or 1)
if(bb.mergeIds[mAc]or mAc==bb.planId)and(tAc or aAc[mAc])and(not lAc or GAc>lAc.score)then
lAc={id=mAc,top=wAc,fresh=tAc,near=uAc or 0,n=vAc or 0,coming=aAc[mAc],score=GAc}
end
end
bb.planId,bb.freshM=lAc and lAc.id,lAc and lAc.fresh and lAc.fresh.m
bb.mergeHeldAt=(Qzc and lAc and lAc.fresh)and(bb.mergeHeldAt or bb.wave())or nil
if not lAc then
return F.status(Dud[3706],Dud[3769])
end
local HAc,IAc=bb.wave(),(bb.total or 30)-bb.wave()
local JAc=(bb.pressure or 0)>=math.min(O.dangerReach,((bb.depth and bb.depth.units>0 and bb.depth.covEnd)or 1)*0.9)
local KAc=lAc.fresh
local LAc=not JAc and IAc>3
lAc.waits=KAc and KAc.lvl<=lAc.top.lvl and lAc.top.lvl<lAc.top.max and LAc or false
local MAc=(not KAc or KAc.lvl>=lAc.top.lvl)and lAc.coming and LAc
local NAc=bb.cloneCard and lAc.top.lvl>=lAc.top.max and LAc
local OAc=KAc and KAc.lvl>lAc.top.lvl and lAc.near<0.3*KAc.dps
lAc.ready=Qzc and KAc~=nil and not OAc and(not(lAc.waits or MAc or NAc)or HAc-(bb.mergeHeldAt or HAc)>=5)
bb.holdNoCardAt=(lAc.waits and not Qzc)and(bb.holdNoCardAt or HAc)or nil
lAc.hold=lAc.waits and(Qzc or HAc-(bb.holdNoCardAt or HAc)<4)
bb.mergePlan=lAc
F.status(Dud[3706],KAc and string.format(Dud[3770],V.name(lAc.id),lAc.n,lAc.n==1 and Dud[3771]or Dud[3772],KAc.lvl,lAc.ready and Dud[3773]or(Qzc and Dud[3774]or Dud[3775]))or string.format(Dud[3776],V.name(lAc.id)))
end
function bb.mergeHold(PAc)
local QAc=bb.mergePlan
return QAc and QAc.hold and QAc.fresh and QAc.fresh.m==PAc or false
end
function bb.mergeBoost(RAc)
local SAc=bb.mergePlan
if not(SAc and SAc.top.m==RAc and(SAc.fresh or SAc.coming))then
return 1
end
return bb.mergeHeldAt and 2 or 1.3
end
function bb.mergeSpot(TAc)
if not(bb.random and bb.mergeIds[TAc.id])then
return nil
end
local UAc,VAc
for WAc,XAc in ipairs(bb.mine or{})do
if XAc._stats.id.Value==TAc.id then
local YAc,ZAc=pcall(bb.liveDps,XAc,TAc.id)
ZAc=YAc and ZAc or 0
if not VAc or ZAc>VAc then
UAc,VAc=XAc,ZAc
end
