end
task.delay(2,function()
if not(_Ac and _Ac.Parent)then
return
end
local bBc,cBc=pcall(bb.liveDps,_Ac,_Ac._stats.id.Value)
if not bBc then
return
end
local dBc=aBc.own+1.5*aBc.near
local eBc=P.fh.merge or{n=0,ratio=0}
if dBc>0 then
eBc.n,eBc.ratio=eBc.n+1,eBc.ratio+cBc/dBc
end
P.fh.merge=eBc
local fBc=_Ac._stats.id.Value
P.fh.noMerge=P.fh.noMerge or{}
