if hBc>0 and gBc<0.1*hBc then
P.fh.noMerge[fBc]=(P.fh.noMerge[fBc]or 0)+1
elseif hBc>0 and gBc>=0.5*hBc then
P.fh.noMerge[fBc]=nil
end
F.log(1,Dud[3723],string.format(Dud[3777],V.name(_Ac._stats.id.Value),U.fmt(aBc.own),U.fmt(cBc),aBc.lvl,U.fmt(aBc.near),U.fmt(dBc),aBc.top))
end)
end
function bb.farmMergeOk()
