end
return iBc.ratio/iBc.n>=0.8
end
function bb.farmMergePair()
local jBc={}
for kBc,lBc in ipairs(bb.mine or{})do
local mBc=lBc._stats.id.Value
if V.isFarm(mBc)and lBc._stats:FindFirstChild(Dud[1751])then
jBc[mBc]=jBc[mBc]or{}
table.insert(jBc[mBc],lBc)
end
end
for nBc,oBc in pairs(jBc)do
if#oBc>=2 then
table.sort(oBc,function(pBc,qBc)
return pBc._stats.upgrade.Value<qBc._stats.upgrade.Value
end)
for rBc,sBc in ipairs(oBc)do
local tBc,uBc=U.flat(sBc:GetPivot().Position),sBc._stats.range.Value
local vBc,wBc=0,0
for xBc,yBc in ipairs(oBc)do
if yBc~=sBc and(U.flat(yBc:GetPivot().Position)-tBc).Magnitude<=uBc then
vBc,wBc=vBc+(tonumber(yBc._stats.farm_amount.Value)or 0),wBc+1
end
end
if wBc>0 then
return sBc,vBc,wBc
end
end
end
end
