ZBc.n,ZBc.dmg,ZBc.cost=ZBc.n+1,ZBc.dmg+(XBc/UBc-1),ZBc.cost+(1-YBc/VBc)
P.fh.idol=ZBc
F.log(1,Dud[3582],string.format(Dud[3780],V.name(PBc.id.Value),(XBc/UBc-1)*100,(1-YBc/VBc)*100))
end)
end
function bb.spells()
local _Bc=N.session()
