function bb.trainCount()
local WCc=P.train.on
if not(WCc and bb.trainee)then
return
end
local XCc=0
for YCc,ZCc in ipairs(bb.mine)do
local _Cc=ZCc._stats
local aDc=_Cc:FindFirstChild(Dud[3518])and _Cc.uuid.Value
local bDc=aDc==bb.trainee and _Cc:FindFirstChild(WCc.what==Dud[2020]and Dud[3800]or Dud[2207])
if bDc then
XCc=XCc+(tonumber(bDc.Value)or 0)
end
end
bb.trainTk=math.max(bb.trainTk or 0,XCc)
F.status(Dud[2613],string.format(Dud[3801],V.name(WCc.id),bb.trainTk,WCc.what,U.fmt(WCc.have+(WCc.got or 0)+bb.trainTk),U.fmt(WCc.need)))
end
function bb.trainDone(cDc,dDc)
local eDc=P.train.on
if not(eDc and bb.trainee)then
return
end
bb.trainCount()
local fDc=bb.trainTk or 0
eDc.got=(eDc.got or 0)+fDc
local gDc=P.trainSim[cDc]and tonumber(P.trainSim[cDc].tk)
if not bb.joinedMid then
local hDc=P.train.real[cDc]or{n=0,sum=0}
hDc.n,hDc.sum=hDc.n+1,hDc.sum+fDc
P.train.real[cDc]=hDc
if gDc and gDc>0 then
local iDc=P.train.cal
iDc.real,iDc.sim,iDc.n=(iDc.real or 0)+fDc,(iDc.sim or 0)+gDc,(iDc.n or 0)+1
end
end
table.insert(P.train.log,1,{key=cDc,got=fDc,won=dDc,at=os.time()})
while#P.train.log>20 do
table.remove(P.train.log)
end
F.log(1,Dud[2606],string.format(Dud[3802],V.name(eDc.id),fDc,eDc.what,dDc and Dud[2106]or Dud[2107],gDc and string.format(Dud[3803],gDc)or Dud[570],U.fmt(hb.realHave(eDc)),U.fmt(eDc.need)))
if not dDc then
P.train.bad[cDc]=os.time()+6*3600
F.log(1,Dud[2606],Dud[3804])
end
