function bb.finish()
if bb.finished then
return
end
bb.finished=true
local jDc
local kDc=U.now()
while U.now()-kDc<8 do
jDc=bb.result or(N.GUIS.results_ui and N.GUIS.results_ui.settings)
if jDc then
break
end
task.wait(0.25)
end
local lDc=jDc and jDc.victory or false
local mDc=bb.infinite and bb.wave()or nil
if mDc then
lDc=true
end
local nDc=bb.key
local oDc=W.rec(nDc)
if mDc and not bb.joinedMid and not bb.stopping then
oDc.waveSum,oDc.waveN=(tonumber(oDc.waveSum)or 0)+mDc,(tonumber(oDc.waveN)or 0)+1
oDc.waveBest=math.max(tonumber(oDc.waveBest)or 0,mDc)
