local pDc={}
for qDc,rDc in pairs(jDc)do
table.insert(pDc,type(rDc)==Dud[1645]and(qDc..Dud[2033])or(qDc..Dud[2034]..tostring(rDc)))
end
table.sort(pDc)
F.log(1,Dud[2036],Dud[3805]..table.concat(pDc,Dud[1755]))
