local sDc=jDc and jDc.stats and tonumber(jDc.stats.time_taken)or(os.clock()-(bb.startClock or os.clock()))
local tDc=jDc and((tonumber(jDc.gem_reward)or 0)+(tonumber(jDc.first_completion_gems)or 0))or 0
local uDc=N.GS.CURRENT_EVENT_RESOURCE or Dud[2266]
local vDc=jDc and jDc.resource_reward and tonumber(jDc.resource_reward[uDc])or 0
if not bb.joinedMid then
oDc.runs=oDc.runs+1
if lDc then
oDc.wins=oDc.wins+1
oDc.streak=0
elseif bb.kind==Dud[1662]and vDc>0 then
oDc.streak=0
else
oDc.streak=(oDc.streak or 0)+1
end
oDc.sec=oDc.sec+sDc
oDc.timed=(tonumber(oDc.timed)or 0)+1
end
if lDc then
if bb.ld._gamemode==Dud[1682]or bb.kind==Dud[1683]then
P.cleared[bb.ld.id..Dud[1770]..tostring(bb.ld._difficulty or Dud[1815])]=os.time()
end
